"""Registry of the named contract fixtures (docs/testing/strategy.md#named-contract-fixtures).

Each fixture has a stable ID, the milestones whose Tests section names it, an
optional generator, and its cases. A fixture without a generator is a stub: its
owning milestone adds the generator. tests/bpy_free/test_fixture_registry.py keeps
the IDs and milestones in sync with the docs. Other fixtures join the registry
when a milestone assigns them in docs/testing/requirements.yaml.

A case is one run of an operation on the fixture with a declared outcome, citing
the matrix rows its assertions check and the qualification phase it belongs to
(docs/testing/acceptance.md#bespoke-fixtures). Tests select cases by fixture and
name; tests/bpy_free/test_fixture_cases.py checks the cases against the matrix.
"""

from __future__ import annotations

from collections.abc import Callable
from contextlib import AbstractContextManager
from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path
from typing import Literal

from . import appearance, copies, evaluation, interaction, source_access, transaction

# A generator writes the fixture into a fresh directory and yields a handle to it.
# It is a context manager so in-process state (open stages, cache entries) is released on exit.
Generator = Callable[[Path], AbstractContextManager[object]]


def _schema_versions(dest: Path) -> AbstractContextManager[object]:
    """F-SCHEMA-VERSIONS' generator, imported when used: it imports the records' package, which imports bpy."""
    from . import records

    return records.schema_versions(dest)


class Operation(StrEnum):
    SYNCHRONIZE = "synchronize"
    CACHE = "cache"
    CLEANUP = "cleanup"
    DETACH = "detach"
    REMOVE_BINDING = "remove binding"


class Outcome(StrEnum):
    SUCCESS = "success"
    COMPLETED_WITH_ISSUES = "completed with issues"
    FAILURE = "failure"


@dataclass(frozen=True)
class Case:
    name: str  # unique within its fixture
    operation: Operation
    outcome: Outcome
    requirements: tuple[str, ...]  # matrix row IDs its assertions check
    phase: Literal[1, 2]  # the highest phase among those rows


@dataclass(frozen=True)
class Fixture:
    id: str
    title: str
    milestones: tuple[str, ...]  # milestones whose Tests section names this fixture
    build: Generator | None = None  # None: a stub, generated by its owning milestone
    cases: tuple[Case, ...] = ()


